<script setup lang="ts">
import AdminSidePanel from '@/Components/AdminSidePanel.vue';
import EnButton from '@/Components/EnButton.vue';
import EnCard from '@/Components/EnCard.vue';
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';

type Supplier = { id: number; name: string; contact_name?: string; phone?: string; email?: string };
type Product = { id: number; name: string; sku: string };
type Purchase = { id: number; quantity: number; unit_cost_minor: number; purchased_at: string; supplier: Supplier; product: Product; note?: string };
const props = defineProps<{ suppliers: Supplier[]; products: Product[]; purchases: Purchase[] }>();
const tenant = String(route().params.tenant);
const mobilePanelOpen = ref(false);
const supplierForm = useForm({ name: '', contact_name: '', phone: '', email: '', address: '' });
const receivingForm = useForm({ supplier_id: null as number | null, product_id: null as number | null, quantity: 1, unit_cost_cedis: 0, purchased_at: new Date().toISOString().slice(0, 10), note: '' });
const submitSupplier = (): void => supplierForm.post(route('tenant.suppliers.store', { tenant }), { onSuccess: () => supplierForm.reset() });
const receiveStock = (): void => receivingForm.transform((data) => ({ ...data, unit_cost_minor: Math.round(Number(data.unit_cost_cedis) * 100) })).post(route('tenant.suppliers.receive', { tenant }), { onSuccess: () => receivingForm.reset('quantity', 'unit_cost_cedis', 'note') });
const formatPrice = (minor: number): string => new Intl.NumberFormat('en-GH', { style: 'currency', currency: 'GHS' }).format(minor / 100);
</script>
<template>
    <Head title="Suppliers" />
    <main class="min-h-screen bg-neutral-50"><div class="mx-auto flex min-h-screen max-w-[1600px]"><AdminSidePanel :tenant="tenant" current="suppliers" :mobile-open="mobilePanelOpen" @close="mobilePanelOpen = false" /><section class="min-w-0 flex-1 px-4 py-6 sm:px-8 sm:py-10"><div class="mx-auto max-w-7xl space-y-8"><button type="button" class="mb-5 inline-flex rounded-md border border-neutral-200 bg-white px-3 py-2 text-sm lg:hidden" @click="mobilePanelOpen = true">Open admin navigation</button><header><p class="text-sm font-semibold text-red-700">Purchasing</p><h1 class="mt-1 text-3xl font-bold">Suppliers</h1><p class="mt-2 text-sm text-neutral-500">Manage supplier contacts and record received stock with quantities, costs, and dates.</p></header><div class="grid gap-6 xl:grid-cols-2"><EnCard><h2 class="text-lg font-semibold">Add supplier</h2><form class="mt-5 space-y-3" @submit.prevent="submitSupplier"><input v-model="supplierForm.name" required placeholder="Supplier name" class="min-h-11 w-full rounded-md border px-3 text-sm" /><input v-model="supplierForm.contact_name" placeholder="Contact person" class="min-h-11 w-full rounded-md border px-3 text-sm" /><input v-model="supplierForm.phone" placeholder="Phone" class="min-h-11 w-full rounded-md border px-3 text-sm" /><input v-model="supplierForm.email" type="email" placeholder="Email" class="min-h-11 w-full rounded-md border px-3 text-sm" /><textarea v-model="supplierForm.address" placeholder="Address" class="min-h-20 w-full rounded-md border px-3 py-2 text-sm" /><EnButton type="submit" :loading="supplierForm.processing">Save supplier</EnButton></form></EnCard><EnCard><h2 class="text-lg font-semibold">Receive stock</h2><form class="mt-5 grid gap-3 sm:grid-cols-2" @submit.prevent="receiveStock"><select v-model="receivingForm.supplier_id" required class="min-h-11 rounded-md border px-3 text-sm"><option :value="null">Select supplier</option><option v-for="supplier in props.suppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }}</option></select><select v-model="receivingForm.product_id" required class="min-h-11 rounded-md border px-3 text-sm"><option :value="null">Select product</option><option v-for="product in props.products" :key="product.id" :value="product.id">{{ product.name }} · {{ product.sku }}</option></select><label class="text-sm text-neutral-600">Quantity<input v-model.number="receivingForm.quantity" type="number" min="1" required class="mt-1 min-h-11 w-full rounded-md border px-3 text-sm" /></label><label class="text-sm text-neutral-600">Unit cost (cedis)<input v-model.number="receivingForm.unit_cost_cedis" type="number" min="0" step="0.01" required class="mt-1 min-h-11 w-full rounded-md border px-3 text-sm" /></label><label class="text-sm text-neutral-600">Purchase date<input v-model="receivingForm.purchased_at" type="date" required class="mt-1 min-h-11 w-full rounded-md border px-3 text-sm" /></label><input v-model="receivingForm.note" placeholder="Reference or note" class="min-h-11 rounded-md border px-3 text-sm sm:mt-6" /><EnButton type="submit" :loading="receivingForm.processing" class="sm:col-span-2">Record stock received</EnButton></form></EnCard></div><EnCard><h2 class="text-lg font-semibold">Purchase history</h2><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="border-b text-xs uppercase text-neutral-500"><tr><th class="px-3 py-3">Date</th><th class="px-3 py-3">Supplier</th><th class="px-3 py-3">Product</th><th class="px-3 py-3">Quantity</th><th class="px-3 py-3">Unit cost</th><th class="px-3 py-3">Total</th></tr></thead><tbody><tr v-for="purchase in props.purchases" :key="purchase.id" class="border-b last:border-0"><td class="px-3 py-3">{{ purchase.purchased_at }}</td><td class="px-3 py-3 font-semibold">{{ purchase.supplier?.name }}</td><td class="px-3 py-3">{{ purchase.product?.name }}</td><td class="px-3 py-3">{{ purchase.quantity }}</td><td class="px-3 py-3">{{ formatPrice(purchase.unit_cost_minor) }}</td><td class="px-3 py-3 font-semibold">{{ formatPrice(purchase.unit_cost_minor * purchase.quantity) }}</td></tr></tbody></table><p v-if="!props.purchases.length" class="py-5 text-sm text-neutral-500">No stock receipts recorded yet.</p></div></EnCard></div></section></div></main>
</template>
